// Shared by the SleipnirLoader component and the boot screen that index.html
// shows before the bundle mounts (injected by vite.config.ts), so both draw
// the exact same loader. Pure strings only — vite.config imports this file,
// so it can't pull in React or `?raw` imports.

export const LOADER_CSS = `
.sleipnir-loader { line-height: 0; }
.sleipnir-loader svg { display: block; width: 100%; height: auto; }
`

// Wraps horse-gallop.svg (generated by tools/generate-horse-morph.mjs) for
// display: the size comes from the container, and the horse paints in the
// container's currentColor.
export function loaderMarkup(horseSvg: string): string {
  const svg = horseSvg
    .replace(/<!--[\s\S]*?-->\s*/g, '')
    .replace(/ width="\d+" height="\d+"/, '')
    .replace('<svg ', '<svg aria-hidden="true" ')
  return `<div class="sleipnir-loader" role="img" aria-label="Loading">${svg}</div>`
}

